{
 "summary": "The file defines finite two-player entangled games, finite-dimensional tensor-product quantum strategies, the entangled value ω*(G) as a supremum of win probabilities, and the n-fold parallel repetition G^n. It states (1) Theorem 1.1: there is a universal c>0 such that ω*(G^n) ≤ exp(-c·ε^13/(ε+log(|A||B|))·n) whenever ε=1-ω*(G)>0 and A, B are nonempty, and (2) the qualitative statement that ω*(G)<1 gives ω*(G^n) ≤ C·exp(-c·n). Both statements look faithful. The main caveat is that ω* is modelled as a sup over finite-dimensional strategies on Type-level state spaces, and the qualitative statement carries an extra constant C that the paper's form lacks. Both are minor.",
 "glossary": [
  {"decl": "Game", "line": 12, "plain": "Finite two-player one-round game: a question distribution μ(x,y) (nonnegative, sums to 1) and a predicate V(x,y,a,b).", "standard_concept": "Finite two-player one-round game G=(X,Y,A,B,μ,V)", "matches_standard": "yes", "note": "Normalization forces X and Y to be nonempty. A and B may be empty, which is handled by the Nonempty hypotheses."},
  {"decl": "Game.repeat", "line": 23, "plain": "n-fold parallel repetition G^n: product question weights, and the predicate is the conjunction of coordinate-wise predicates.", "standard_concept": "G^{⊗n}", "matches_standard": "yes", "note": "For n=0 it is the trivial one-point game with value 1."},
  {"decl": "DensityMatrix", "line": 50, "plain": "Positive semidefinite complex matrix of trace 1.", "standard_concept": "Quantum state", "matches_standard": "yes", "note": ""},
  {"decl": "POVM", "line": 55, "plain": "Family of PSD effects indexed by outcomes that sum to the identity.", "standard_concept": "POVM", "matches_standard": "yes", "note": ""},
  {"decl": "Strategy", "line": 60, "plain": "Finite-dimensional bipartite state on Alice × Bob (both types in Type 0) together with a POVM on A for each x for Alice and a POVM on B for each y for Bob.", "standard_concept": "Finite-dimensional tensor-product entangled strategy", "matches_standard": "yes", "note": "Universe restricted to Type; this does not matter for the value. Commuting-operator strategies are not included."},
  {"decl": "Strategy.outcomeProbability", "line": 84, "plain": "Re tr(ρ (E_a^x ⊗ F_b^y)).", "standard_concept": "Born rule", "matches_standard": "yes", "note": ""},
  {"decl": "Strategy.winProbability", "line": 87, "plain": "Σ_{x,y} μ(x,y) Σ_{a,b: V=1} P(a,b|x,y).", "standard_concept": "Winning probability", "matches_standard": "yes", "note": ""},
  {"decl": "entangledValue", "line": 94, "plain": "sup over strategies of the winning probability, ω*(G).", "standard_concept": "Entangled value ω*(G)", "matches_standard": "yes", "note": "sSup of the range over real numbers. The range is bounded by 1, and it is nonempty when A and B are nonempty. If A or B is empty there are no strategies and sSup ∅ = 0, but the main theorem excludes this case."},
  {"decl": "HasExponentialBound", "line": 102, "plain": "∃ c>0, C>0, ∀ n, v n ≤ C·exp(-c n).", "standard_concept": "Exponential decay, matching the paper's ω*(G^n) ≤ exp(-c_G n) for n≥1", "matches_standard": "partly", "note": "The paper's form has no prefactor C and only needs n≥1. Lean allows C and includes n=0, where v 0 = 1, so C≥1 is needed. The two forms agree qualitatively."},
  {"decl": "StandardQuantumParallelRepetition", "line": 108, "plain": "ω*(G)<1 → ω*(G^n) decays exponentially in n.", "standard_concept": "Quantum Parallel Repetition Conjecture", "matches_standard": "yes", "note": "Up to the C-prefactor caveat. It carries no nonempty-alphabet hypothesis, and the empty-alphabet cases are harmless."}
 ],
 "lean_claims": [
  {"theorem": "distributionUniformExponential", "line": 112, "plain": "There is c>0 such that for every game G on finite types (in Type 0) with A, B nonempty, ω*(G)<1, and every n≥1: ω*(G^n) ≤ exp(-c·(1-ω*)^13/((1-ω*)+log(|A||B|))·n)."},
  {"theorem": "standardQuantumParallelRepetition", "line": 130, "plain": "For every finite game G (types in Type 0), if ω*(G)<1 then there exist c,C>0 with ω*(G^n) ≤ C·exp(-c n) for all n≥0."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is a universal c_qs>0 such that for every finite two-player one-round entangled game with nonempty answer alphabets and ε=1-ω*(G)>0, for all n≥1, ω*(G^n) ≤ exp(-c_qs ε^13/(ε+log(|A||B|))·n)."},
  {"ref": "Quantum Parallel Repetition Conjecture (answered affirmatively)", "plain": "For every finite entangled game with ω*(G)<1 there is c_G>0 with ω*(G^n) ≤ exp(-c_G n) for all n≥1."}
 ],
